      const kc2 = KC[i0] + (KC[i1] - KC[i0]) * ff, wc = WC[i0] + (WC[i1] - WC[i0]) * ff;
      const env = DA[d] * amp0 / (0.35 + r * 2.4) / (0.5 + tau * 0.28);   // steepness
      // viscous cutoff: fine ripples die fast — this is why you only ever glimpse them
